-- ============================================
-- NACIONALIDADES
-- ============================================
CREATE TABLE IF NOT EXISTS "NACIONALIDADES" (
    "ID_NACIONALIDAD" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_NACIONALIDADES" PRIMARY KEY,
    "NOMBRE" VARCHAR(80) NOT NULL CONSTRAINT "UQ_NACIONALIDADES_NOMBRE" UNIQUE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
